commit 0618f37df67c462c8f948155fb13ff433a9cf113
Author: anthnel <anthoni.devops@proton.me>
Date:   Tue Nov 10 12:56:25 2026 +0100

    test: guard viewports that receive keys against horizontal scrolling (DEVDESK-201)

    Entire-Checkpoint: 14a4591a7ed2

diff --git a/internal/app/help_scroll_test.go b/internal/app/help_scroll_test.go
new file mode 100644
index 0000000..0ea0f05
--- /dev/null
+++ b/internal/app/help_scroll_test.go
@@ -0,0 +1,71 @@
+package app
+
+import (
+	"strings"
+	"testing"
+
+	"charm.land/bubbles/v2/key"
+
+	"github.com/anthnel/devdesk/internal/ui/testutil"
+)
+
+// DEVDESK-201 D2. bubbles/viewport v2 binds Left/Right (and h/l) to horizontal
+// scrolling by default. Rule 135 gives <-/-> to drill-down and value cycling and
+// a bare letter is an action, so the help overlay must not scroll sideways.
+//
+// These two tests are non-regression guards: the overlay already sets a
+// KeyMap without Left/Right (arrowOnlyScroll), so they are green on the
+// current code. The red of the rule is proven in keymap's
+// TestViewportKeyMapDetector, which feeds the guard a violating source.
+
+func TestArrowOnlyScrollBindsNoHorizontalKey(t *testing.T) {
+	km := arrowOnlyScroll()
+	for name, b := range map[string]key.Binding{"Left": km.Left, "Right": km.Right} {
+		if keys := b.Keys(); len(keys) != 0 {
+			t.Errorf("%s is bound to %v; the help overlay must not scroll horizontally", name, keys)
+		}
+	}
+	for name, b := range map[string]key.Binding{
+		"Up": km.Up, "Down": km.Down, "PageUp": km.PageUp, "PageDown": km.PageDown,
+		"HalfPageUp": km.HalfPageUp, "HalfPageDown": km.HalfPageDown, "Left": km.Left, "Right": km.Right,
+	} {
+		for _, k := range b.Keys() {
+			if k == "h" || k == "l" || k == "left" || k == "right" {
+				t.Errorf("%s binds %q", name, k)
+			}
+		}
+	}
+}
+
+func TestHelpOverlayIgnoresHorizontalKeys(t *testing.T) {
+	view := &fakeView{title: "view"}
+	a := router(t, view)
+	a.maybeOpenHelp(testutil.Key("?"))
+	if !a.showHelp {
+		t.Fatal("the help did not open (the fake view must implement help.Provider)")
+	}
+	// Content both taller and wider than the viewport, so any scroll key that
+	// is bound has room to move the offset.
+	lines := make([]string, 200)
+	for i := range lines {
+		lines[i] = strings.Repeat("0123456789", 40)
+	}
+	a.helpViewport.SetContent(strings.Join(lines, "\n"))
+
+	for _, name := range []string{"left", "right", "h", "l"} {
+		a.handleHelpKeyMsg(testutil.Key(name))
+		if x, y := a.helpViewport.XOffset(), a.helpViewport.YOffset(); x != 0 || y != 0 {
+			t.Fatalf("after %q: XOffset=%d YOffset=%d, want 0 and 0", name, x, y)
+		}
+	}
+	for _, name := range []string{"down", "pgdown"} {
+		before := a.helpViewport.YOffset()
+		a.handleHelpKeyMsg(testutil.Key(name))
+		if a.helpViewport.YOffset() <= before {
+			t.Errorf("%q did not scroll the help down (YOffset %d -> %d)", name, before, a.helpViewport.YOffset())
+		}
+	}
+	if x := a.helpViewport.XOffset(); x != 0 {
+		t.Errorf("XOffset = %d after vertical scrolling, want 0", x)
+	}
+}
diff --git a/internal/ui/keymap/viewport_keymap_scan_test.go b/internal/ui/keymap/viewport_keymap_scan_test.go
new file mode 100644
index 0000000..39ce138
--- /dev/null
+++ b/internal/ui/keymap/viewport_keymap_scan_test.go
@@ -0,0 +1,134 @@
+package keymap
+
+import (
+	"go/ast"
+	"go/parser"
+	"go/token"
+	"path/filepath"
+	"regexp"
+	"strconv"
+	"testing"
+)
+
+// DEVDESK-201 D2. bubbles/viewport v2 scrolls horizontally on Left/Right/h/l by
+// default. Rule 135 gives <-/-> to drill-down and value cycling, and a bare
+// letter is an action. A viewport that is handed keys must therefore replace the
+// default KeyMap with one that has no Left/Right.
+//
+// The guard: in a production package, every `X.Update(` whose receiver's last
+// selector name matches (?i)viewport|vp must be accompanied, in the same package,
+// by an assignment `X.KeyMap = ...` for the same X.
+//
+// Limit (stated, not hidden): it keys on the field/variable name. A viewport
+// stored under a name that does not contain "viewport" (or is not "vp") escapes
+// it, and so does a KeyMap set through a helper that returns the model.
+// The real code today has one such site (internal/app/help_overlay.go) and is
+// compliant, so TestEveryViewportFedKeysSetsAKeyMap is a non-regression guard;
+// TestViewportKeyMapDetector is what proves the guard can fire.
+
+var viewportName = regexp.MustCompile(`(?i)viewport|^vp$`)
+
+// lastName returns the last identifier of x (a.b.c -> "c"), "" if x is not a
+// chain of selectors/identifiers.
+func lastName(x ast.Expr) string {
+	switch v := x.(type) {
+	case *ast.Ident:
+		return v.Name
+	case *ast.SelectorExpr:
+		return v.Sel.Name
+	}
+	return ""
+}
+
+// viewportKeyFindings returns "path:line" for each X.Update( on a viewport-named
+// X in files (one package) with no X.KeyMap = assignment anywhere in files.
+func viewportKeyFindings(fset *token.FileSet, files map[string]*ast.File) []string {
+	withKeyMap := map[string]bool{}
+	for _, f := range files {
+		ast.Inspect(f, func(n ast.Node) bool {
+			if as, ok := n.(*ast.AssignStmt); ok {
+				for _, l := range as.Lhs {
+					if sel, ok := l.(*ast.SelectorExpr); ok && sel.Sel.Name == "KeyMap" {
+						withKeyMap[lastName(sel.X)] = true
+					}
+				}
+			}
+			return true
+		})
+	}
+	var out []string
+	for path, f := range files {
+		ast.Inspect(f, func(n ast.Node) bool {
+			call, ok := n.(*ast.CallExpr)
+			if !ok {
+				return true
+			}
+			sel, ok := call.Fun.(*ast.SelectorExpr)
+			if !ok || sel.Sel.Name != "Update" {
+				return true
+			}
+			name := lastName(sel.X)
+			if name != "" && viewportName.MatchString(name) && !withKeyMap[name] {
+				out = append(out, filepath.ToSlash(path)+":"+strconv.Itoa(fset.Position(sel.Sel.Pos()).Line))
+			}
+			return true
+		})
+	}
+	return out
+}
+
+func TestViewportKeyMapDetector(t *testing.T) {
+	tests := []struct {
+		name string
+		src  string
+		want int
+	}{
+		{"fed keys, default KeyMap", "package p\nfunc f(m M, msg any) { m.detailsViewport, _ = m.detailsViewport.Update(msg) }\n", 1},
+		{"fed keys, plain variable vp", "package p\nfunc f(msg any) { vp, _ = vp.Update(msg) }\n", 1},
+		{"fed keys, KeyMap set", "package p\nfunc f(a A, msg any) {\n\ta.helpViewport.KeyMap = k()\n\ta.helpViewport, _ = a.helpViewport.Update(msg)\n}\n", 0},
+		{"KeyMap set for another viewport only", "package p\nfunc f(a A, msg any) {\n\ta.helpViewport.KeyMap = k()\n\ta.textViewport, _ = a.textViewport.Update(msg)\n}\n", 1},
+		{"not a viewport", "package p\nfunc f(a A, msg any) { a.spinner, _ = a.spinner.Update(msg) }\n", 0},
+		{"viewport never fed keys", "package p\nfunc f(a A) { a.textViewport.SetContent(\"x\") }\n", 0},
+	}
+	for _, tc := range tests {
+		t.Run(tc.name, func(t *testing.T) {
+			fset := token.NewFileSet()
+			file, err := parser.ParseFile(fset, "x.go", tc.src, 0)
+			if err != nil {
+				t.Fatalf("parse: %v", err)
+			}
+			got := viewportKeyFindings(fset, map[string]*ast.File{"x.go": file})
+			if len(got) != tc.want {
+				t.Errorf("findings = %v, want %d", got, tc.want)
+			}
+		})
+	}
+}
+
+func TestEveryViewportFedKeysSetsAKeyMap(t *testing.T) {
+	fset := token.NewFileSet()
+	byDir := map[string]map[string]*ast.File{}
+	files := 0
+	walkProduction(t, func(_ *token.FileSet, path string, _ *ast.File) {
+		// walkProduction parses with its own FileSet; reparse into ours so
+		// positions are comparable and files group by package directory.
+		f, err := parser.ParseFile(fset, path, nil, 0)
+		if err != nil {
+			t.Fatalf("parse %s: %v", path, err)
+		}
+		files++
+		dir := filepath.Dir(path)
+		if byDir[dir] == nil {
+			byDir[dir] = map[string]*ast.File{}
+		}
+		byDir[dir][path] = f
+	})
+	if files == 0 {
+		t.Fatal("no production file scanned — the scan is broken, not the code")
+	}
+	for _, pkg := range byDir {
+		for _, where := range viewportKeyFindings(fset, pkg) {
+			t.Errorf("%s: a viewport is fed keys but its package never sets <viewport>.KeyMap; the default scrolls on Left/Right/h/l (Rule 135) — assign a KeyMap without them (DEVDESK-201)", where)
+		}
+	}
+}
