			m := loadedModel(t)
			m, _ = step(t, m, testutil.Key("/"))
			m, _ = step(t, m, testutil.Paste(tc.paste))
			if got := m.table.FilterBar().SearchQuery(); got != tc.want {
				t.Errorf("search query = %q after pasting %q, want %q", got, tc.paste, tc.want)
			}
		})
	}
}

