// wantsBlink reports whether the view on screen has a row that blinks.
func (a *App) wantsBlink() bool {
	view, ok := a.views[a.currentView].(BlinkingView)
	return ok && view.WantsBlink()
}

// applyMotion points the animation at the motion a config asks for. It is
// called wherever the router takes a new config (context switch, every save);
// the constructor sets the field directly because it has no Cmd to return.
func (a *App) applyMotion(cfg *config.Config) tea.Cmd {
	return a.setMotionStatic(cfg.App.StaticMotion())
}

// setMotionStatic pins the blink phase on and stops blink-only chains. The view
// on screen is handed the pinned frame at once, otherwise it would keep an off
// phase until the next tick that may never come.
func (a *App) setMotionStatic(on bool) tea.Cmd {
	a.motionStatic = on
	if !on {
		return nil
	}
	a.anim.blinkOn = true
	return a.sendFrameTo(a.currentView)
}

func (a *App) update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		a.resize(msg.Width, msg.Height)
		return a, nil

	case tea.KeyPressMsg:
		return a.handleKeyMsg(msg)

	case tea.PasteMsg:
		return a.handlePasteMsg(msg)

	// ── Contexts and themes ──────────────────────────────────────────────
	case configuration.ConfigSavedMsg:
		return a.handleConfigSaved(msg)

	case contextNamesLoadedMsg:
		return a.handleContextNamesLoaded(msg)

	case MCPServerStartedMsg:
		return a.handleMCPServerStarted(msg)

	case mcpJobsRequestMsg:
		return a.handleMCPJobsRequest(msg)

	case mcpForwardsRequestMsg:
		return a.handleMCPForwardsRequest(msg)

	case mcpStartRequestMsg:
		return a.handleMCPStartRequest(msg)

	case mcpCancelRequestMsg:
		return a.handleMCPCancelRequest(msg)

	case jobs.RefusedMsg:
		return a.handleMCPRefused(msg)

	case ContextSwitchCompleteMsg:
		return a.handleContextSwitchComplete(msg)

	case ContextSwitchErrorMsg:
		return a.handleContextSwitchError(msg)

	case ContextListMsg:
		return a.handleContextList(msg)

	// ── GitLab authentication ────────────────────────────────────────────
	case auth.AuthResultMsg:
		return a.handleAuthResult(msg)

	case auth.LogoutCompleteMsg:
		return a.handleLogoutComplete(msg)

	case ForgeAutoLoginMsg:
		return a.handleAutoLoginResult(msg)

	// ── Long-running work ────────────────────────────────────────────────
	// The animation: one chain for the whole application, held by the router
	// (D5) — see animation.go.
	case animationTickMsg:
		return a.handleAnimationTick(msg)

	// ── The scanners' detection (§3.86) — see scan_tools.go ─────────────
	case scanToolsDetectedMsg:
		return a.handleScanToolsDetected(msg)

	case shared.ScanToolsDetectRequestMsg:
		return a, a.detectScanTools()

	// ── The forge index — see forge_index.go ────────────────────────────
	case forgeIndexLoadedMsg:
		return a.handleForgeIndexLoaded(msg)

